const m=e=>{const s=e%19,o=Math.floor(e/100),r=e%100,l=Math.floor(o/4),c=o%4,n=Math.floor((o+8)/25),t=Math.floor((o-n+1)/3),a=(19*s+o-l-t+15)%30,i=Math.floor(r/4),g=r%4,d=(32+2*c+2*i-a-g)%7,u=Math.floor((s+11*a+22*d)/451),f=Math.floor((a+d-7*u+114)/31),h=(a+d-7*u+114)%31+1;return new Date(e,f-1,h)},D=[[1,1,"Año Nuevo"],[5,1,"Día del Trabajo"],[5,21,"Glorias Navales"],[6,29,"San Pedro y San Pablo"],[7,16,"Virgen del Carmen"],[8,15,"Asunción de la Virgen"],[9,18,"Independencia Nacional"],[9,19,"Glorias del Ejército"],[10,12,"Encuentro Dos Mundos"],[10,31,"Iglesias Evangélicas"],[11,1,"Todos los Santos"],[12,8,"Inmaculada Concepción"],[12,25,"Navidad"]],M=e=>{const s=e.getMonth()+1,o=e.getDate(),r=e.getFullYear(),l=D.find(([a,i])=>a===s&&i===o);if(l)return l[2];const c=m(r),n=new Date(c);n.setDate(n.getDate()-2);const t=new Date(c);return t.setDate(t.getDate()-1),e.getTime()===n.getTime()?"Viernes Santo":e.getTime()===t.getTime()?"Sábado Santo":null},S=e=>M(e)!==null;export{S as e,M as n};
